@@ -88,9 +88,17 @@ final class SyncEngine {
     func merge(local: Note, remote: Note) -> [Note] {
-        // Last write wins.
-        return [local.modified > remote.modified ? local : remote]
+        guard local.body != remote.body else { return [local] }
+        // Keep both: the newer one in place, the older as a copy.
+        let (newer, older) = local.modified > remote.modified ? (local, remote) : (remote, local)
+        var copy = older
+        copy.id = UUID()
+        copy.title += " (\(older.device))"
+        return [newer, copy]
     }

